# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SAKİN MİMİN (مْ) ÜÇ HÂLİ — GENEL SINIFLANDIRMA ŞEMASI</text>\n  <rect x="250" y="42" width="200" height="36" rx="8" fill="#1e293b"/>\n  <text x="350" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#ffffff">Sakin Mim (مْ) + Sonraki Harf</text>\n  <rect x="22" y="96" width="208" height="145" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="126" y="120" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">1. İhfa-i Şefevî (Dudak İhfası)</text>\n  <text x="36" y="144" font-size="11.5" font-weight="bold" fill="#1e40af">• Koşul: مْ + ب (Bâ harfi)</text>\n  <text x="36" y="166" font-size="11" fill="#334155">• Okunuş: Dudaklar hafifçe</text>\n  <text x="36" y="182" font-size="11" fill="#334155">  değdirilir, mim gizlenerek</text>\n  <text x="36" y="198" font-size="11" fill="#334155">  1,5 elif gunneli okunur.</text>\n  <text x="126" y="224" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">Örnek: تَرْمِيهِمْ بِحِجَارَةٍ</text>\n  <rect x="246" y="96" width="208" height="145" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="120" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">2. İdgam-ı Misleyn Meal-Gunne</text>\n  <text x="260" y="144" font-size="11.5" font-weight="bold" fill="#166534">• Koşul: مْ + م (Mim harfi)</text>\n  <text x="260" y="166" font-size="11" fill="#334155">• Okunuş: İki mim birleşir,</text>\n  <text x="260" y="182" font-size="11" fill="#334155">  şeddeli tek mim gibi 1,5 elif</text>\n  <text x="260" y="198" font-size="11" fill="#334155">  gunneli (genizden) okunur.</text>\n  <text x="350" y="224" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">Örnek: لَهُمْ مَا يَشَاءُونَ</text>\n  <rect x="470" y="96" width="208" height="145" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="574" y="120" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">3. İzhar-ı Şefevî (Dudak İzharı)</text>\n  <text x="484" y="144" font-size="11.5" font-weight="bold" fill="#92400e">• Koşul: مْ + Diğer 26 Harf</text>\n  <text x="484" y="166" font-size="11" fill="#334155">  (ب ve م dışındaki tüm harfler)</text>\n  <text x="484" y="184" font-size="11" fill="#334155">• Okunuş: Gunnesiz, tutmadan</text>\n  <text x="484" y="200" font-size="11" fill="#334155">  açık ve net şekilde okunur.</text>\n  <text x="574" y="224" text-anchor="middle" font-size="12" font-weight="bold" fill="#a16207">Örnek: أَلَمْ تَرَ · لَهُمْ فِيهَا</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">İHFA-İ ŞEFEVÎ (DUDAK İHFASI) VE İDGAM-I MİSLEYN MEAL-GUNNE</text>\n  <rect x="28" y="48" width="310" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="183" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">İhfa-i Şefevî: مْ + ب</text>\n  <text x="44" y="102" font-size="11.5" fill="#334155">• Şefevî = Dudakla ilgili demektir (م ve ب</text>\n  <text x="44" y="120" font-size="11.5" fill="#334155">  harflerinin ikisi de dudak harfidir).</text>\n  <text x="44" y="146" font-size="11.5" fill="#334155">• Kur\'an-ı Kerim\'den Örnekler:</text>\n  <text x="54" y="168" font-size="12" font-weight="bold" fill="#1e40af">1) تَرْمِيهِمْ بِحِجَارَةٍ (Fîl suresi, 4)</text>\n  <text x="54" y="190" font-size="12" font-weight="bold" fill="#1e40af">2) إِنَّ رَبَّهُمْ بِهِمْ (Âdiyât suresi, 11)</text>\n  <text x="54" y="212" font-size="12" font-weight="bold" fill="#1e40af">3) وَمَا هُمْ بِمُؤْمِنِينَ (Bakara suresi, 8)</text>\n  <rect x="362" y="48" width="310" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="517" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">İdgam-ı Misleyn Meal-Gunne: مْ + م</text>\n  <text x="378" y="102" font-size="11.5" fill="#334155">• Sakin mimden sonra harekeli mim (مَ، مِ، مُ)</text>\n  <text x="378" y="120" font-size="11.5" fill="#334155">  geldiğinde şeddeli ve gunneli okunur.</text>\n  <text x="378" y="146" font-size="11.5" fill="#334155">• Kur\'an-ı Kerim\'den Örnekler:</text>\n  <text x="388" y="168" font-size="12" font-weight="bold" fill="#166534">1) أَطْعَمَهُمْ مِنْ جُوعٍ (Kureyş suresi, 4)</text>\n  <text x="388" y="190" font-size="12" font-weight="bold" fill="#166534">2) عَلَيْهِمْ مُؤْصَدَةٌ (Hümeze suresi, 8)</text>\n  <text x="388" y="212" font-size="12" font-weight="bold" fill="#166534">3) فِي قُلُوبِهِمْ مَرَضٌ (Bakara suresi, 10)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">İZHAR-I ŞEFEVÎ (DUDAK İZHARI) VE DİKKAT EDİLECEK HARFLER</text>\n  <rect x="28" y="48" width="310" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="183" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">İzhar-ı Şefevî Örnekleri (مْ + 26 Harf)</text>\n  <text x="44" y="102" font-size="11.5" fill="#334155">• Kelime İçi Örnekler:</text>\n  <text x="54" y="122" font-size="11.5" font-weight="bold" fill="#92400e">الْحَمْدُ (مْ + د) · أَنْعَمْتَ (مْ + ت) · يَمْكُرُونَ (مْ + ك)</text>\n  <text x="44" y="150" font-size="11.5" fill="#334155">• İki Kelime Arası Örnekler:</text>\n  <text x="54" y="170" font-size="11.5" font-weight="bold" fill="#92400e">أَلَمْ تَرَ (مْ + ت) · أَلَمْ نَشْرَحْ (مْ + ن)</text>\n  <text x="54" y="192" font-size="11.5" font-weight="bold" fill="#92400e">لَهُمْ عَذَابٌ (مْ + ع) · صِرَاطِهِمْ غَيْرِ (مْ + غ)</text>\n  <text x="44" y="218" font-size="11" fill="#475569">* Hepsi gunnesiz ve tutulmadan açıkça okunur.</text>\n  <rect x="362" y="48" width="310" height="190" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="517" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Vav (و) ve Fâ (ف) Harflerine Özel Dikkat!</text>\n  <text x="378" y="102" font-size="11" fill="#334155">• و (vav) ve ف (fâ) harfleri de dudak bölgesinden</text>\n  <text x="378" y="120" font-size="11" fill="#334155">  çıktığı için sakin mimden sonra geldiklerinde</text>\n  <text x="378" y="138" font-size="11" font-weight="bold" fill="#991b1b">  yanlışlıkla ihfa yapılmamalı, NET İZHAR yapılmalıdır!</text>\n  <text x="378" y="168" font-size="11.5" font-weight="bold" fill="#991b1b">• مْ + ف → لَهُمْ فِيهَا / هُمْ فِيهَا (İzhar-ı Şefevî)</text>\n  <text x="378" y="194" font-size="11.5" font-weight="bold" fill="#991b1b">• مْ + و → عَلَيْهِمْ وَلَا / هُمْ وَأَزْوَاجُهُمْ (İzhar-ı Şefevî)</text>\n  <text x="378" y="218" font-size="10.5" fill="#475569">* Dudaklar tam kapanıp hemen açılarak mim net okunur.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
